// Regola 0000: testo di commento che occupa spazio come le spiegazioni del motore vero, con le soglie,
// le eccezioni e il riferimento alla decisione che la giustifica (D-00), su due righe di commento.
function regola0000(x: number, note: string[]): number {
  const etichetta = "regola 0000: passo 0 del calcolo di prova, con un testo abbastanza lungo";
  if (x < 0) {
    note.push(etichetta + " su un valore negativo");
  }
  return (x * 31 + 0) % 1000003;
}

